@font-face{font-family:Tajawal;font-weight:400;src:url(fonts/tajawal-400.woff2) format("woff2");font-display:swap}
@font-face{font-family:Tajawal;font-weight:500;src:url(fonts/tajawal-500.woff2) format("woff2");font-display:swap}
@font-face{font-family:Tajawal;font-weight:700;src:url(fonts/tajawal-700.woff2) format("woff2");font-display:swap}
:root{--bg:#e9ebee;--panel:#fff;--ink:#1a1d22;--muted:#5d6672;--line:#d5d9df;--brass:#8c6a1c;--brass-2:#b8923a;--plate-fg:#2a1f07;--soft:#eef0f3;--danger:#b42d2d;--ok:#2f7d57}
html[data-theme=dark]{--bg:#121418;--panel:#1a1d23;--ink:#eceae4;--muted:#9aa2ad;--line:#2b303a;--brass:#d2a94c;--brass-2:#e5c370;--plate-fg:#241a05;--soft:#222630;--danger:#ff8585;--ok:#6fcf9b}
*{box-sizing:border-box}
html,body{margin:0;background:var(--bg);color:var(--ink)}
body{font:400 15px/1.6 Tajawal,system-ui,sans-serif;-webkit-text-size-adjust:100%;min-height:100vh}
button,input,select,textarea{font:inherit;color:inherit}button{cursor:pointer;background:none;border:0;padding:0}
:focus-visible{outline:3px solid var(--brass-2);outline-offset:2px;border-radius:6px}
.ic{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;flex:none}
.grow{flex:1}
/* القفل */
#lock{min-height:100vh;display:grid;place-items:center;padding:24px}
.gate{width:min(380px,100%);display:grid;gap:10px;justify-items:center;text-align:center}
.gate h1{margin:6px 0 0;font-size:26px;line-height:1.3}.sub{margin:0 0 8px;color:var(--muted)}
.gate form{width:100%;display:grid;gap:10px}
.gate input{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:13px 14px;text-align:center;font-size:17px;width:100%;letter-spacing:.04em}
.dial{position:relative;width:132px;height:132px;display:grid;place-items:center;color:var(--brass)}
.dial svg:first-child{position:absolute;inset:0;width:100%;height:100%}
.dial .ring{fill:none;stroke:var(--brass);stroke-width:2.5}.dial .tick{stroke:var(--brass);stroke-width:2;transform-origin:60px 60px}.dial .core{fill:var(--panel);stroke:var(--line);stroke-width:1.5}
.dial .dl{width:34px;height:34px;position:relative;stroke-width:1.9}
.gate.busy .tick{animation:spin 1.1s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.gate.shake{animation:shake .35s}
@keyframes shake{25%{transform:translateX(8px)}75%{transform:translateX(-8px)}}
.err{min-height:1.4em;margin:0;color:var(--danger);font-weight:500}.warn{margin:0;font-size:13.5px;color:var(--muted);background:var(--soft);padding:9px 12px;border-radius:8px;text-align:start}
.meter{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin:-2px 0}.meter i{height:5px;border-radius:9px;background:var(--line)}
.meter i.s1{background:var(--danger)}.meter i.s2{background:#d98b2b}.meter i.s3,.meter i.s4{background:var(--ok)}
/* الأزرار */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:42px;padding:8px 16px;border-radius:10px;border:1px solid var(--line);background:var(--panel);font-weight:500}
.btn.pri{background:linear-gradient(180deg,var(--brass-2),var(--brass));border-color:var(--brass);color:var(--plate-fg);font-weight:700}
.btn.quiet{background:transparent}.btn.danger{color:var(--danger);border-color:var(--danger);background:transparent}.btn.small{min-height:34px;padding:4px 12px;font-size:14px}
.btn:disabled{opacity:.55;cursor:wait}
.icon{display:inline-grid;place-items:center;width:42px;height:42px;border-radius:10px;color:var(--ink)}.icon:hover{background:var(--soft)}.icon.s{width:38px;height:38px;color:var(--muted)}.icon.s:hover{color:var(--ink)}
a.icon{text-decoration:none}
.lnk{color:var(--brass);text-decoration:underline;text-underline-offset:3px;font-weight:500}
/* الواجهة */
#bar{position:sticky;top:0;z-index:5;display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:12px 20px;background:var(--bg);border-bottom:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:12px;min-width:0}.brand .ic{width:34px;height:34px;color:var(--brass)}.brand .ic.turn{animation:turn .9s cubic-bezier(.3,.7,.2,1)}
@keyframes turn{from{transform:rotate(-200deg)}to{transform:none}}
.brand h1{margin:0;font-size:19px;line-height:1.25}.brand small{color:var(--muted)}
.search{flex:1 1 240px;display:flex;align-items:center;gap:8px;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:0 12px;color:var(--muted)}
.search input{flex:1;border:0;background:none;padding:10px 0;outline:0;min-width:0;color:var(--ink)}.search:focus-within{outline:3px solid var(--brass-2)}
.acts{display:flex;gap:6px;align-items:center}
#sections{max-width:1000px;margin:0 auto;padding:20px;display:grid;gap:16px}
.drawer{background:var(--panel);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.drawer>header{display:flex;align-items:center;background:var(--soft)}
.dh{flex:1;display:flex;align-items:center;gap:10px;padding:12px 16px;text-align:start;min-width:0}
.dh h2{margin:0;font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dh small{margin-inline-start:auto;color:var(--muted)}
.fold{transition:transform .2s;color:var(--muted)}.drawer.shut .fold{transform:rotate(90deg)}
.plate{background:linear-gradient(180deg,var(--brass-2),var(--brass));color:var(--plate-fg);font-size:12.5px;font-weight:700;padding:1px 10px;border-radius:5px;box-shadow:inset 0 1px 0 #fff6,0 1px 2px #0003;white-space:nowrap}
.rows{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr))}
.item{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px 10px 8px;padding-inline:16px 8px;border-top:1px dashed var(--line)}
.it-b{display:grid;min-width:0}.it-b small{color:var(--muted)}
.val{overflow-wrap:anywhere;font-weight:500;white-space:pre-wrap}.val.sens{font-family:ui-monospace,Menlo,monospace;font-size:14px;direction:ltr;text-align:end}
.val.link{color:var(--brass);text-decoration:underline;text-underline-offset:3px;direction:ltr;text-align:end}
.mask{letter-spacing:.2em;color:var(--muted)}
.it-a{display:flex;flex:none}
.none{grid-column:1/-1;margin:0;padding:14px 16px;color:var(--muted);border-top:1px dashed var(--line)}
.empty{text-align:center;padding:48px 16px;display:grid;justify-items:center;gap:8px}.empty .mark{width:68px;height:68px;border-radius:50%;background:var(--soft);display:grid;place-items:center;color:var(--brass)}.empty .mark .ic{width:32px;height:32px}.empty h2{margin:0}.empty p{margin:0 0 10px;color:var(--muted)}
/* نوافذ */
.veil{position:fixed;inset:0;background:#05070acc;z-index:30}
.sheet{position:fixed;z-index:31;inset-block:0;inset-inline-start:0;width:min(460px,100%);background:var(--bg);display:flex;flex-direction:column;box-shadow:0 0 40px #0008}
.sheet>header{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;background:var(--panel);border-bottom:1px solid var(--line)}.sheet h2{margin:0;font-size:18px}
.sheet-b{padding:16px;overflow:auto;flex:1;display:grid;gap:12px;align-content:start}
.frm{display:grid;gap:12px}.fld{display:grid;gap:5px}.fld>span{font-size:13.5px;color:var(--muted)}
.fld input,.fld select,.fld textarea{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:10px 12px;min-height:44px;width:100%;resize:vertical}
.fld .bad,.bad{border-color:var(--danger)!important}
.with{display:grid;gap:8px}
.checks{display:grid;gap:8px}.checks label{display:flex;gap:10px;align-items:center}.checks input{width:20px;height:20px;accent-color:var(--brass)}
.acts2{display:flex;gap:8px;align-items:center;margin-top:4px}
.sh{margin:10px 0 0;font-size:15px;color:var(--brass)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.note{margin:0;color:var(--muted);font-size:13.5px}
.ask{position:fixed;inset:0;z-index:40;display:grid;place-items:center;padding:16px}.ask .box{position:relative;z-index:41;background:var(--panel);border-radius:12px;padding:20px;width:min(380px,100%)}.ask p{margin:0 0 14px;font-weight:500}.ask .acts2{justify-content:flex-end}
#toast{position:fixed;bottom:24px;inset-inline:0;margin:auto;width:fit-content;max-width:92vw;background:var(--ink);color:var(--bg);padding:9px 18px;border-radius:99px;opacity:0;pointer-events:none;transition:opacity .2s;z-index:60}#toast.on{opacity:1}
@media(max-width:640px){
  #bar{padding:10px 14px;gap:8px}.brand{flex:1}.acts{width:100%;justify-content:space-between}.acts .btn{flex:1}.search{order:3;flex-basis:100%}
  #sections{padding:14px}.rows{grid-template-columns:1fr}
  .sheet{inset:auto 0 0 0;width:100%;max-height:92vh;border-radius:16px 16px 0 0}
}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}

'use strict';
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const E = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const norm = (s) => String(s || '').toLowerCase().replace(/[ً-ْـ]/g, '').replace(/[أإآ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه');
const IC = {
  vault: '<rect x="3.5" y="4.5" width="17" height="15" rx="2.5"/><circle cx="12" cy="12" r="3.2"/><path d="M12 8.8v-1.6M12 16.8v-1.6M8.8 12H7.2M16.8 12h-1.6M7 19.500V21M17 19.500V21"/>',
  lock: '<rect x="5" y="10.500" width="14" height="9.500" rx="2"/><path d="M8 10.500V8a4 4 0 0 1 8 0v2.500"/>',
  gear: '<circle cx="12" cy="12" r="3"/><path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.600 5.600l2.100 2.100M16.300 16.300l2.100 2.100M5.600 18.400l2.100-2.100M16.300 7.700l2.100-2.100"/>',
  plus: '<path d="M12 5v14M5 12h14"/>', x: '<path d="M6 6l12 12M18 6L6 18"/>',
  copy: '<rect x="8.500" y="8.500" width="11" height="11" rx="2"/><path d="M15.500 8.500V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v7.500a2 2 0 0 0 2 2h2.500"/>',
  eye: '<path d="M2.500 12S6 5.500 12 5.500 21.500 12 21.500 12 18 18.500 12 18.500 2.500 12 2.500 12z"/><circle cx="12" cy="12" r="2.800"/>',
  eyeoff: '<path d="M3 3l18 18M10 6a9 9 0 0 1 2-.5C18 5.500 21.500 12 21.500 12a17 17 0 0 1-3.200 4M6.300 7.700A17 17 0 0 0 2.500 12S6 18.500 12 18.500a9 9 0 0 0 3.500-.7"/>',
  edit: '<path d="M4 20h4L19 9l-4-4L4 16z"/>', ext: '<path d="M14 4h6v6M20 4l-9 9M18 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h5"/>',
  search: '<circle cx="11" cy="11" r="6.500"/><path d="M16 16l4.500 4.500"/>', chev: '<path d="M6 9l6 6 6-6"/>', down: '<path d="M12 4v11M7 11l5 5 5-5M5 20h14"/>', up: '<path d="M12 16V5M7 9l5-5 5 5M5 20h14"/>',
  dice: '<rect x="4" y="4" width="16" height="16" rx="3"/><circle cx="9" cy="9" r="1"/><circle cx="15" cy="15" r="1"/><circle cx="15" cy="9" r="1"/><circle cx="9" cy="15" r="1"/>',
};
const ic = (n, c = '') => `<svg class="ic ${c}" viewBox="0 0 24 24" aria-hidden="true">${IC[n].replace(/(\d)\.(\d)00/g, '$1.$2')}</svg>`;

/* ===== الحالة ===== */
let META = { title: 'الخزنة الرقمية', auto: 2 }, REC = null, KEY = null, SALT = null, IT = ITER, D = null, query = '';
const shown = new Set(); let fails = 0, idleT = 0, hideT = 0, toastT = 0;
const starter = () => ({ sections: [{ id: 's' + uid(), title: 'مرحباً بك في الخزنة', badge: 'قسم توضيحي', collapsed: false, items: [
  { id: 'i' + uid(), title: 'دليل البداية', val: 'احذف هذا القسم أو أضف أقسامك وعناصرك بالأزرار أعلاه. كل شيء مشفّر بكلمة مرورك.', link: false, sens: false },
  { id: 'i' + uid(), title: 'رابط تجريبي', val: 'https://example.com', link: true, sens: false },
  { id: 'i' + uid(), title: 'كود سرّي تجريبي', val: 'EXAMPLE-SECRET-2026', link: false, sens: true }] }] });
function toast(m) { const t = $('#toast'); t.textContent = m; t.classList.add('on'); clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove('on'), 2400); }
async function save() { REC = await sealWith(KEY, SALT, IT, D); await Alaisai.set('vault', REC); }
async function saveMeta() { await Alaisai.set('meta', META); }
function safeUrl(v) {
  const s = String(v || '').trim(); if (!s || /\s/.test(s)) return null;
  if (/^(https?:\/\/|mailto:|tel:)/i.test(s)) return s;
  if (/^[\w.-]+\.[a-z]{2,}([/?#].*)?$/i.test(s)) return 'https://' + s;
  return null;
}
async function copy(text) {
  try { await navigator.clipboard.writeText(text); } catch (e) { const t = document.createElement('textarea'); t.value = text; t.style.cssText = 'position:fixed;opacity:0'; document.body.appendChild(t); t.select(); try { document.execCommand('copy'); } catch (x) { /* لا شيء */ } t.remove(); }
  toast('تم النسخ');
}

/* ===== القفل ===== */
function dial() {
  const ticks = Array.from({ length: 36 }, (_, i) => `<line x1="60" y1="${i % 3 ? 9 : 5}" x2="60" y2="14" transform="rotate(${i * 10} 60 60)"/>`).join('');
  return `<div class="dial" aria-hidden="true"><svg viewBox="0 0 120 120"><circle class="ring" cx="60" cy="60" r="55"/><g class="tick">${ticks}</g><circle class="core" cx="60" cy="60" r="30"/></svg>${ic('lock', 'dl')}</div>`;
}
function renderLock(msg) {
  const L = $('#lock'); $('#app').hidden = true; L.hidden = false; document.title = META.title;
  const first = !REC;
  L.innerHTML = `<div class="gate">${dial()}<h1>${E(META.title)}</h1><p class="sub">${first ? 'أنشئ كلمة مرور لحماية بياناتك' : 'أدخل كلمة المرور لفتح الخزنة'}</p><form id="lf" novalidate autocomplete="off"><input type="password" id="p1" placeholder="${first ? 'كلمة مرور جديدة' : 'كلمة المرور'}" autocomplete="${first ? 'new-password' : 'current-password'}" aria-label="كلمة المرور">${first ? `<div class="meter" aria-hidden="true"><i></i><i></i><i></i><i></i></div><input type="password" id="p2" placeholder="أعد كتابة كلمة المرور" autocomplete="new-password" aria-label="تأكيد كلمة المرور"><p class="warn">لا يمكن استرجاع الخزنة إن نسيت كلمة المرور. اكتبها في مكان آمن.</p>` : ''}<p class="err" id="lerr" role="alert">${E(msg || '')}</p><button class="btn pri" type="submit" id="lbtn">${first ? 'إنشاء الخزنة' : 'فتح الخزنة'}</button></form></div>`;
  const f = $('#lf'), p1 = $('#p1');
  if (first) p1.addEventListener('input', () => { const s = strength(p1.value); $$('.meter i').forEach((e, i) => { e.className = i < s ? 's' + s : ''; }); });
  f.addEventListener('submit', first ? setup : unlock);
  setTimeout(() => p1.focus(), 50);
}
function busy(on) { const g = $('.gate'); if (g) g.classList.toggle('busy', on); const b = $('#lbtn'); if (b) { b.disabled = on; b.textContent = on ? 'جارٍ التحقق…' : (REC ? 'فتح الخزنة' : 'إنشاء الخزنة'); } }
const lerr = (m) => { const e = $('#lerr'); if (e) e.textContent = m; };
async function setup(e) {
  e.preventDefault(); const a = $('#p1').value, b = $('#p2').value;
  if (a.length < 6) return lerr('كلمة المرور قصيرة، استخدم 6 أحرف على الأقل.');
  if (a !== b) return lerr('كلمتا المرور غير متطابقتين.');
  busy(true);
  try { SALT = crypto.getRandomValues(new Uint8Array(16)); IT = ITER; KEY = await deriveKey(a, SALT, IT); D = starter(); await save(); await saveMeta(); enter(); }
  catch (x) { busy(false); lerr('تعذّر إنشاء الخزنة على هذا المتصفح.'); }
}
async function unlock(e) {
  e.preventDefault(); const pw = $('#p1').value; if (!pw) return lerr('أدخل كلمة المرور.');
  busy(true);
  try {
    const salt = unb64(REC.s), key = await deriveKey(pw, salt, REC.it || ITER), data = await openWith(key, REC);
    SALT = salt; IT = REC.it || ITER; KEY = key; D = data; fails = 0; enter();
  } catch (x) {
    fails++; const wait = Math.min(8, fails * 1.5);
    renderLock('كلمة المرور غير صحيحة.'); $('.gate').classList.add('shake');
    const b = $('#lbtn'); b.disabled = true; setTimeout(() => { if (b.isConnected) b.disabled = false; }, wait * 1000);
  }
}
function lock(msg) {
  KEY = null; D = null; SALT = null; shown.clear(); query = ''; closeSheet();
  $('#sections').innerHTML = ''; renderLock(msg);
}
function enter() {
  $('#lock').hidden = true; $('#app').hidden = false; document.title = META.title; render(); poke();
  const d = $('#bar .ic.brand'); if (d) d.classList.add('turn');
}
function poke() { clearTimeout(idleT); if (KEY && META.auto > 0) idleT = setTimeout(() => lock('أُقفلت الخزنة تلقائياً بعد فترة خمول.'), META.auto * 60000); }
['pointerdown', 'keydown', 'scroll'].forEach((ev) => addEventListener(ev, poke, { passive: true }));
document.addEventListener('visibilitychange', () => { if (document.hidden && KEY) { clearTimeout(hideT); hideT = setTimeout(() => { if (document.hidden && KEY) lock('أُقفلت الخزنة لأنك غادرت الشاشة.'); }, 30000); } else clearTimeout(hideT); });

/* ===== العرض ===== */
function render() {
  $('#bar').innerHTML = `<div class="brand">${ic('vault', 'brand')}<div><h1>${E(META.title)}</h1><small>${D.sections.reduce((a, s) => a + s.items.length, 0)} عنصر في ${D.sections.length} قسم</small></div></div><label class="search">${ic('search')}<input id="q" type="search" placeholder="ابحث بالعنوان أو القسم" value="${E(query)}" autocomplete="off" aria-label="بحث"></label><div class="acts"><button class="btn quiet" data-a="newSec">${ic('plus')}<span>قسم</span></button><button class="btn pri" data-a="newItem">${ic('plus')}<span>عنصر</span></button><button class="icon" data-a="settings" aria-label="الإعدادات">${ic('gear')}</button><button class="icon" data-a="lock" aria-label="قفل الخزنة">${ic('lock')}</button></div>`;
  drawSections(); const q = $('#q'); q.addEventListener('input', () => { query = q.value; drawSections(); });
}
function matchItem(it, s, q) { return norm(it.title + ' ' + s.title + ' ' + s.badge + ' ' + (it.sens ? '' : it.val)).includes(q); }
function drawSections() {
  const q = norm(query.trim()), root = $('#sections');
  if (!D.sections.length) { root.innerHTML = `<div class="empty"><div class="mark">${ic('vault')}</div><h2>الخزنة فارغة</h2><p>أنشئ قسماً ثم أضف إليه روابطك وحساباتك وأكوادك.</p><button class="btn pri" data-a="newSec">${ic('plus')}قسم جديد</button></div>`; return; }
  const html = D.sections.map((s) => {
    const items = q ? s.items.filter((it) => matchItem(it, s, q)) : s.items;
    if (q && !items.length && !norm(s.title + s.badge).includes(q)) return '';
    const open = q ? true : !s.collapsed;
    return `<section class="drawer${open ? '' : ' shut'}" data-sec="${s.id}"><header><button class="dh" data-a="fold" data-id="${s.id}" aria-expanded="${open}">${ic('chev', 'fold')}<h2>${E(s.title)}</h2><span class="plate">${E(s.badge)}</span><small>${s.items.length}</small></button><button class="icon" data-a="editSec" data-id="${s.id}" aria-label="تعديل القسم ${E(s.title)}">${ic('edit')}</button></header>${open ? `<div class="rows">${items.length ? items.map((it) => row(it)).join('') : `<p class="none">${s.items.length ? 'لا نتائج في هذا القسم.' : 'لا عناصر بعد.'} <button class="lnk" data-a="newItem" data-sec="${s.id}">أضف عنصراً</button></p>`}</div>` : ''}</section>`;
  }).join('');
  root.innerHTML = html || `<div class="empty"><h2>لا نتائج</h2><p>جرّب كلمة أخرى.</p></div>`;
}
function row(it) {
  const url = it.link ? safeUrl(it.val) : null, hid = it.sens && !shown.has(it.id);
  const val = hid ? '<span class="mask" aria-label="قيمة مخفية">••••••••••</span>' : url ? `<a class="val link" href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(it.val)}</a>` : `<span class="val${it.sens ? ' sens' : ''}" dir="auto">${E(it.val)}</span>`;
